from pathlib import Path
base=Path('/var/tmp/rgnix-forward-20261001')
commands=[('lookups',['sudo','-n','python3','.local/forward-20261001/metric_lookups.py'])]
for phase,binary in [('before',Path('/var/tmp/rgnix-dispatch-20261001/rgnix-idle-probe')),('metrics',base/'rgnix-metrics')]:
 for kind,script in [('alloc','.local/allocator-opt-20260928/allocations.py'),('primitives','scripts/profile_http_primitives.py')]:
  commands.append((kind+'-'+phase,['sudo','-n','python3',script,'--profile','/var/tmp/rgnix-worker-20261001/profile-local/result.json','--matrix','/var/tmp/rgnix-worker-20261001/product-1k.json','--engines','hyper','--binary',str(binary),'--work-dir',str(base/(kind+'-'+phase))]))
results=[]
for name,command in commands:
 with (base/(name+'.log')).open('w') as log:r=subprocess.run(command,stdout=log,stderr=log)
 results.append(dict(name=name,command=command,returncode=r.returncode));(base/'probes.json').write_text(json.dumps(results,indent=2)+'\n')
